using System;using System.Collections.Generic;using System.Web.Script.Serialization;using PipDesktop;
class VisitsTests {
 static int checks;static void Check(bool b,string name){if(!b)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static void Main(){JavaScriptSerializer j=new JavaScriptSerializer();RelaySaved old=j.Deserialize<RelaySaved>("{\"code\":\"old\",\"friends\":[],\"seen\":[]}");Check(old.gifts!=null&&old.giftCounts!=null,"old save gains collection defaults");Check(j.Deserialize<RelayMessage>("{\"action\":\"offer\"}").features==0,"legacy peers never falsely enable games");
 RelaySaved s=new RelaySaved();RelayFriend f=new RelayFriend{name="Пип друга"};s.friends.Add(f);FriendVisit v=new FriendVisit{id="v1",features=2,gift="leaf"};Check(VisitLife.Remember(s,f,v,true,10)&&f.meetings==1&&s.giftCounts["leaf"]==1,"first arrival remembers meeting and gift");Check(!VisitLife.Remember(s,f,v,true,11)&&f.meetings==1&&s.gifts.Count==1,"replayed arrival does not duplicate gifts or meetings");
 for(int i=2;i<52;i++)VisitLife.Remember(s,f,new FriendVisit{id="v"+i,features=2,gift="toy"},true,i);Check(s.gifts.Count==40&&s.giftCounts["toy"]==50&&s.giftCounts["leaf"]==1,"bounded gift history preserves all collection totals");VisitLife.Remember(s,f,new FriendVisit{id="sender",features=2,gift="card"},false,90);Check(!s.giftCounts.ContainsKey("card"),"sender cannot award a gift to itself");VisitLife.Remember(s,f,new FriendVisit{id="legacy",features=0,gift="card"},true,91);Check(!s.giftCounts.ContainsKey("card"),"legacy visit does not invent a gift");
 RelaySaved restored=j.Deserialize<RelaySaved>(j.Serialize(s));Check(restored.giftCounts["leaf"]==1&&restored.friends[0].meetings==53,"collection and counts serialize");Check(VisitLife.Gift("none")&&!VisitLife.Gift("file://secret")&&!VisitLife.Game("external-command"),"only known gifts and games are accepted");
 foreach(string game in new[]{"ball","chase","rest"}){bool bounded=true;for(double t=0;t<30;t+=.04){DuoFrame p=DuoFrame.At(game,t);bounded&=p.host>=0&&p.host<=1&&p.guest>=0&&p.guest<=1&&p.hostFrame>=0&&p.hostFrame<8&&p.guestFrame>=0&&p.guestFrame<8;}Check(bounded,"scene stays in bounds: "+game);}
 DuoFrame end=DuoFrame.At("ball",31);Check(!end.showBall&&end.hostRow==0&&end.guestRow==0,"game ends with both pets resting");DuoFrame greet=DuoFrame.At("ball",-1);Check(greet.hostRow==3&&greet.guestRow==3,"arrival starts with a mutual greeting");
 Console.WriteLine("ALL "+checks+" CHECKS PASSED");}
}
